/**
 * PUNICODEX — Build Android keyboard assets from the mobile lexicon/directory.
 *
 * Source of truth: mobile/shared/lexicon.js, mobile/shared/unicode-dir.js
 * Generated outputs: android/app/src/main/assets/shared/lexicon.json
 *                    android/app/src/main/assets/shared/keyboard-palette.json
 *
 * GENERATED FILES — DO NOT EDIT BY HAND.
 * Run `npm run generate` to regenerate.
 */
const fs = require('fs');
const path = require('path');

const OUT_DIR = path.join(__dirname, '..', 'android', 'app', 'src', 'main', 'assets', 'shared');

// Ensure output directory exists
if (!fs.existsSync(OUT_DIR)) {
    fs.mkdirSync(OUT_DIR, { recursive: true });
}

// Load lexicon
const { LEXICON } = require(path.join(__dirname, '..', 'mobile', 'shared', 'lexicon.js'));

// Filter and slim lexicon for keyboard (keep fields needed for suggestions + variant display)
const slimLexicon = LEXICON.map(e => ({
    ascii: e.ascii,
    unicode: e.unicode,
    greek: e.greek || "",
    pantheon: e.pantheon,
    tier: e.tier,
    id: e.id || e.ascii,
    variants: (e.variants || []).map(v => ({
        unicode: v.unicode,
        type: v.type || "variant",
        note: v.note || ""
    }))
}));

fs.writeFileSync(path.join(OUT_DIR, 'lexicon.json'), JSON.stringify(slimLexicon), 'utf8');
console.log(`Wrote ${slimLexicon.length} lexicon entries`);

// Load unicode directory and build keyboard palette
const { UNICODE_DIR } = require(path.join(__dirname, '..', 'mobile', 'shared', 'unicode-dir.js'));

// The keyboard palette ships the ENTIRE curated directory — no per-category
// caps. The grid paginates (200 per page with an explicit "showing N of M"
// footer) and every entry is searchable, so depth costs nothing in the UI.
// Curation (which scripts/blocks make the list at all) remains the gate, and
// it lives in the unicode-dir source, not here.
const PALETTE_CATEGORIES_INCLUDED = [
    // Scholarly scripts are the keyboard's reason to exist.
    'latin',
    'greek',
    'cyrillic',
    'runic',
    'gothic',
    'baybayin',
    // Symbols, technical and game sets.
    'math',
    'arrows',
    'symbols',
    'currency',
    'supsub',
    'roman',
    'enclosed',
    'hieroglyphs',
    'alchemical',
    'blocks',
    'box',
    'braille',
    'combining',
    'cuneiform',
    'dingbats',
    'domino',
    'letterlike',
    'linearb',
    'punctuation',
    'shapes',
    // World scripts (v3 expansion) — type any language.
    'hebrew',
    'arabic',
    'devanagari',
    'tamil',
    'thai',
    'tibetan',
    'armenian',
    'georgian',
    'cherokee',
    'hangul',
    'bopomofo',
    'mongolian',
    // Ancient sets — the mythology brand's home turf.
    'phoenician',
    'coptic',
    'glagolitic',
    'ogham',
    'olditalic',
    'ugaritic',
    'oldpersian',
    'greeknumbers',
    'aegean',
    // Utility symbol sets.
    'technical',
    'cjkpunct',
];

// Build a set of characters actually needed to type the lexicon Unicode forms
// so we never truncate them out of the palette.
const usedChars = new Set();
for (const e of LEXICON) {
    for (const ch of e.unicode || '') usedChars.add(ch);
    for (const v of e.variants || []) {
        for (const ch of v.unicode || '') usedChars.add(ch);
    }
}

const PALETTE_CATEGORIES = new Set(PALETTE_CATEGORIES_INCLUDED);
const palette = [];
const addedChars = new Set();
const catCounts = {};

// Pass 1: guarantee every lexicon-used character is included.
for (const e of UNICODE_DIR) {
    if (!PALETTE_CATEGORIES.has(e.category)) continue;
    if (!usedChars.has(e.char)) continue;
    if (addedChars.has(e.char)) continue;
    addedChars.add(e.char);
    catCounts[e.category] = (catCounts[e.category] || 0) + 1;
    palette.push({
        char: e.char,
        code: e.code,
        name: e.name,
        category: e.category,
        keywords: e.keywords
    });
}

// Pass 2: fill remaining slots up to per-category limits.
for (const e of UNICODE_DIR) {
    if (!PALETTE_CATEGORIES.has(e.category)) continue;
    if (addedChars.has(e.char)) continue;
    catCounts[e.category] = catCounts[e.category] || 0;
    addedChars.add(e.char);
    catCounts[e.category]++;
    palette.push({
        char: e.char,
        code: e.code,
        name: e.name,
        category: e.category,
        keywords: e.keywords
    });
}

fs.writeFileSync(path.join(OUT_DIR, 'keyboard-palette.json'), JSON.stringify(palette), 'utf8');
console.log(`Wrote ${palette.length} palette entries`);

// Sidecar README to mark the directory as generated
const readmePath = path.join(OUT_DIR, 'README.md');
fs.writeFileSync(readmePath, `# Generated Android assets

Files in this directory are generated by \`scripts/build-android-assets.js\`.

- \`lexicon.json\` is derived from \`mobile/shared/lexicon.js\`
- \`keyboard-palette.json\` is derived from \`mobile/shared/unicode-dir.js\`

DO NOT EDIT THESE FILES BY HAND.
Run \`npm run generate\` from the repository root to regenerate them.
`, 'utf8');
console.log(`Wrote ${path.relative(path.join(__dirname, '..'), readmePath)}`);
console.log(`Categories in palette:`);
for (const [cat, count] of Object.entries(catCounts).sort((a,b) => b[1]-a[1])) {
    console.log(`  ${cat}: ${count}`);
}
